// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);

        address target = address(0xdead);
        vm.deal(address(c), 1 ether);
        c.sendMoney(target, 0.5 ether, "");

        assertEq(address(c).balance, 0.5 ether);
    }
}
